import {automaticSummary,aggregateRoomsHTML,automaticNote} from './automatic.js?v=20261025-auto';
import {money,nights,ratePlan,guestList} from './engine.js?v=20261025-auto';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const panel=(title,body)=>`<details class="booking-panel" open><summary>${title}<span class="panel-sign" aria-hidden="true"></span></summary><div class="booking-panel-body">${body}</div></details>`;
const date=d=>new Date(d+'T00:00:00Z').toLocaleDateString('vi-VN',{weekday:'short',day:'numeric',month:'long',year:'numeric',timeZone:'UTC'});
export function checkoutContent({allocation,search,config,contact,v,error,automatic=false}){
 const guests=guestList(search),plan=ratePlan(allocation[0].ratePlanId||'standard'),days=nights(search),base=v.quotes.reduce((n,q)=>n+q.lines.filter(l=>l.type==='base').reduce((s,l)=>s+l.amount,0),0);
 const groups=automatic?automaticSummary(allocation,search,config):[];
 const fees=automatic?groups.flatMap(g=>g.fees.filter(f=>f.amount>0).map(f=>({...f,label:f.count+' × '+f.label,room:g.name}))):v.quotes.flatMap((q,i)=>q.lines.filter(l=>l.type!=='base'&&l.amount>0).map(l=>({...l,room:i+1})));
 const field=(key,label,type='text',placeholder='',required=false)=>`<label class="field"><span>${label}${required?' <span class="red">*</span>':''}</span><input id="contact-${key}" data-contact="${key}" type="${type}" value="${esc(contact[key]||'')}" placeholder="${placeholder}" ${required?'required':''}></label>`;
 const radios=(key,options,value)=>options.map(([id,label])=>`<label><input type="radio" name="${key}" data-contact="${key}" value="${id}" ${(contact[key]??value)===id?'checked':''}> ${label}</label>`).join('');
 const rooms=automatic?aggregateRoomsHTML(groups,days)+`<p class="booking-help">${automaticNote}</p>`:[...new Set(allocation.map(a=>a.roomId))].map(id=>{
  const r=config.rooms.find(r=>r.id===id),rows=allocation.map((a,i)=>({a,i})).filter(x=>x.a.roomId===id);
  return `<div class="booking-room"><div class="booking-line"><b>${esc(r.name)}</b><span>× ${rows.length}</span></div><p class="booking-room-desc">${r.id==='a'?'20m² · 1 giường đơn · 1 giường đôi · 1 giường tầng · 1 giường đơn':'Giường có sẵn theo loại phòng đã chọn'} · Gói ${plan.name}</p>${rows.map(({a,i})=>{const gs=guests.filter(g=>a.guestIds.includes(g.id)),adults=gs.filter(g=>g.adult).length,kids=gs.filter(g=>!g.adult);return `<div class="booking-room-guests"><div class="booking-line"><span>Phòng ${i+1} · ${adults} người lớn${kids.length?' · '+kids.map(g=>'trẻ '+g.age+' tuổi').join(', '):''}</span><b>${money(v.quotes[i].total)}</b></div><p>${a.bedIds.length?`${a.bedIds.length} giường phụ · ${gs.filter(g=>a.bedIds.includes(g.id)).map(g=>esc(g.label)).join(', ')}`:'Sử dụng giường có sẵn'}</p><details class="room-cost-detail"><summary>Xem chi tiết giá & phụ thu</summary>${v.quotes[i].lines.map(l=>`<div class="booking-line"><span>${esc(l.label)}</span><span>${money(l.amount)}</span></div>`).join('')}</details></div>`;}).join('')}</div>`;
 }).join('');
 const info=`<div class="booking-hotel"><img src="assets/hotel.jpg" alt="Awaken Da Nang Hotel"><div><small>Khách sạn <span class="stars">★★★★★</span></small><a href="#/customer/hotel">Awaken Da Nang Hotel</a><p>10 Chemin de Montpellier, Đà Nẵng</p><span class="booking-score">7.8</span> Tốt — 7.8 (5)</div></div><div class="booking-dates"><div><small>Nhận phòng</small><strong>${date(search.in)}</strong><span>Từ 14:00</span></div><i aria-hidden="true">»</i><div><small>Trả phòng</small><strong>${date(search.out)}</strong><span>Cho đến 12:00</span></div></div><div class="booking-edit"><a href="#/customer/hotel" data-action="edit-allocation">♢ Sửa thông tin đặt phòng</a></div><div class="booking-line"><span>Tổng thời gian lưu trú</span><span>${days} đêm</span></div><div class="booking-line"><span>Phòng & Người</span><span>${search.adults} người lớn · ${search.children.length} trẻ em · ${allocation.length} phòng</span></div>${rooms}<div class="booking-includes"><span>Bao gồm</span><span>✓ ${plan.name.toUpperCase()} &nbsp; ✓ ${plan.meals}</span></div><div class="booking-cancel"><b>Chính sách hủy phòng</b><p>${plan.id==='standard'?'×':'✓'} ${plan.cancellation}</p><small>${plan.payment}</small></div>`;
 const contactForm=`<p class="booking-demo-note">Đặt thử: sử dụng thông tin minh họa. Không thanh toán hoặc gửi dữ liệu đến khách sạn.</p><div class="contact-top">${field('name','Họ và Tên','text','Khách đặt thử',true)}<fieldset><legend>Giới tính</legend><div class="booking-radios">${radios('gender',[['male','Nam'],['female','Nữ'],['other','Khác']],'')}</div></fieldset></div><div class="contact-pair">${field('email','Email đặt phòng','email','khach@example.com',true)}${field('phone','Số điện thoại','tel','Nhập số điện thoại minh họa',true)}</div><label class="booking-self"><input type="checkbox" data-contact="myself" ${contact.myself!==false?'checked':''}> Tôi đặt chỗ cho chính mình</label><div id="guest-name-field" ${contact.myself!==false?'hidden':''}>${field('guestName','Họ tên khách lưu trú','text','Nhập tên khách lưu trú',contact.myself===false)}</div><label class="field"><span>Yêu cầu đặc biệt</span><textarea data-contact="request" placeholder="Nhập nội dung (không bắt buộc)">${esc(contact.request||'')}</textarea></label><p class="booking-help">Các yêu cầu đặc biệt không đảm bảo sẽ được đáp ứng – tuy nhiên, chỗ nghỉ sẽ cố gắng hết sức để thực hiện. Bạn luôn có thể gửi yêu cầu đặc biệt sau khi hoàn tất đặt phòng của mình!</p><div class="contact-options"><label class="field"><span>Thời gian nhận phòng dự kiến</span><select data-contact="arrival"><option value="">Chọn khung thời gian</option>${['Trước 14:00','14:00 – 16:00','16:00 – 18:00','18:00 – 22:00','Sau 22:00'].map(t=>`<option ${contact.arrival===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field"><span>Mục đích chuyến đi</span><select data-contact="purpose"><option value="">Chọn mục đích</option>${['Du lịch','Công tác','Khác'].map(t=>`<option ${contact.purpose===t?'selected':''}>${t}</option>`).join('')}</select></label><fieldset><legend>Xuất hóa đơn VAT</legend><div class="booking-radios">${radios('vat',[['yes','Có'],['no','Không']],'no')}</div></fieldset></div><small class="booking-ready">Phòng của bạn sẽ sẵn sàng để nhận vào lúc 14:00</small><div id="invoice-fields" ${contact.vat==='yes'?'':'hidden'}><div class="contact-pair">${field('company','Tên công ty','text','Tên công ty',contact.vat==='yes')}${field('taxId','Mã số thuế','text','Mã số thuế',contact.vat==='yes')}</div>${field('companyAddress','Địa chỉ công ty','text','Địa chỉ công ty',contact.vat==='yes')}</div>`;
 const voucher=`<label class="field"><span>Mã voucher</span><div class="voucher-entry"><input data-contact="voucher" value="${esc(contact.voucher||'')}" placeholder="Nhập mã voucher"><button type="button" class="btn secondary" data-action="checkout-voucher">Áp dụng</button></div></label><p id="voucher-feedback" class="booking-help" role="status"></p><div class="booking-line"><span>Dùng Xu <small>(Bạn có 0 xu)</small></span><input type="checkbox" role="switch" disabled aria-label="Dùng Xu — không có xu trong bản thử nghiệm"></div>`;
 const payment=plan.id==='flex'?`<label class="payment-option"><input type="radio" checked disabled> Thanh toán tại chỗ nghỉ</label><p class="booking-help">Gói Linh hoạt: thanh toán tại chỗ nghỉ theo điều kiện gói giá đã chọn.</p>`:`<div class="payment-options">${radios('payment',[['card','Thanh toán bằng thẻ quốc tế <span class="payment-brand">VISA</span> <span class="mastercard">●●</span>'],['domestic','Thanh toán bằng thẻ nội địa <span class="payment-brand">napas</span>'],['qr','Thanh toán với mã QR <span class="payment-brand qr-brand">QR</span>']],'card')}</div>`;
 return `<div class="booking-checkout"><form id="booking-form" novalidate><main class="booking-layout"><div class="booking-left">${panel('Thông tin đặt phòng',info)}${panel('Thông tin liên hệ',contactForm)}${panel('Voucher/ Giảm giá',voucher)}${panel('Phương thức thanh toán',payment+'<p class="booking-help">Bản mô phỏng chỉ lưu đơn đặt thử trong phiên hiện tại. Không thu tiền, không yêu cầu thông tin thẻ.</p>')}</div><aside class="booking-price"><h2>Tóm tắt giá</h2><div class="booking-line"><span>Giá phòng</span><b>${money(base)}</b></div>${automatic?groups.map(g=>`<div class="booking-line price-subline"><span>${esc(g.name)} × ${g.count} phòng × ${days} đêm</span><span>${money(g.base)}</span></div>`).join(''):v.quotes.map((q,i)=>`<div class="booking-line price-subline"><span>Phòng ${i+1} × ${days} đêm</span><span>${money(q.lines.find(l=>l.type==='base').amount)}</span></div>`).join('')}${fees.length?`<div class="booking-line"><span>Phụ thu</span><b>${money(v.total-base)}</b></div>${fees.map(f=>`<div class="booking-line price-subline"><span>${automatic?esc(f.room):'Phòng '+f.room} · ${esc(f.label)}</span><span>${money(f.amount)}</span></div>`).join('')}`:''}<div class="booking-line"><span>Thuế & phí</span><span>Đã bao gồm</span></div><div class="price-room-total"><div class="booking-line"><span>Tổng tiền phòng</span><b>${money(v.total)}</b></div><p>(Bao gồm phụ thu, thuế & phí cho ${days} đêm, ${allocation.length} phòng)</p></div><div class="price-pay-total"><div class="booking-line"><b>Tổng thanh toán</b><strong>${money(v.total)}</strong></div><p>Hoàn xu +${new Intl.NumberFormat('vi-VN').format(Math.floor(v.total*.02))}</p></div><label class="booking-terms"><input type="checkbox" data-contact="terms" ${contact.terms?'checked':''}><span>Tôi đã đọc và đồng ý với <b>Chính sách bảo mật</b> và <b>Quy chế hoạt động</b> của nền tảng</span></label><div id="checkout-error" role="alert" class="booking-error">${esc(error||(!v.valid?v.errors.join(' '):''))}</div><button type="submit" id="booking-submit" class="btn" ${v.valid&&contact.terms?'':'disabled'}>${plan.id==='flex'?'Xác nhận đặt phòng':'Thanh toán'}</button><small class="checkout-simulation">Mô phỏng · Không thu tiền</small></aside></main></form></div>`;
}
